/* ═══ أسئلةُ كتابِ موهبةَ — المستوى الثالث، منقولةٌ بنصِّها ═══════════════
   أرسل الأبُ (١٥ أكتوبر ٢٠٢٦) صفحاتِ «الأسئلة التجريبية» (ص ٤–١١) من:
   «المتميّز في مقياس موهبة — المستوى الثالث · الصفوف ٩–١٠ · إصدار محدَّث
   · إبراهيم قشير · أكاديمية قشير».
   ثمّ أرسل في اليوم نفسِه «ملحق (٨): القدرة الميكانيكية — التروس
   والبكرات» (ص ٢٣٧ → آخر الكتاب) — دفعةٌ ثانيةٌ ذُيِّلت في آخرِ هذا
   الملفّ، وتفصيلُها عند B.sci.

   وهذا يرفع القيدَ المكتوبَ في رأسِ mawhiba3.js («لا أنقل ما لم أره»):
   فتلك مولّداتٌ على أنماطِ المجالاتِ من إعدادي، وهذه أسئلةُ الكتابِ
   بنصِّها وخياراتِها وترتيبِها.

   ── ما نُقل وما تُرك ──
   خمسةٌ وعشرون سؤالًا في الصفحات، نُقل منها ثمانيةَ عشر. والمتروكةُ
   سبعةٌ كلُّها لا تُحلّ بدون صورتِها، ونقلُها نصًّا يغيّر السؤالَ أو
   يجعله بلا حلّ — وهي القاعدةُ نفسُها التي اتُّبعت في كتابِ المستوى
   الأول:
     · مرونة س١ — نمطُ دوائرَ وخطوطٍ في مربّعات
     · مرونة س٤ — أرقامٌ في مثلّثاتٍ متقاطعة (مواضعُها هي السؤال)
     · مرونة س٥ — دورانُ حرفٍ ٩٠°
     · مرونة س٦ — دورانُ قطعةِ أحجية
     · رياضي س٦ — أيُّ الأشكالِ الأربعةِ يتّزن
     · علمي س١ — اتّجاهُ دورانِ ستِّ بكرات
     · علمي س٣ — أيُّ المنحدراتِ أسرع · وس٤ كتلٌ ومسافات · وس٦ مسارُ ارتداد
   ومبادئُ هذي المتروكاتِ مبنيّةٌ أصلًا مولّداتٍ في mawhiba3.js
   (gPulley · gGearDir · gSciForce · gSciEnergy · gMatrixNum).

   و<b>رياضي س٣</b> (الجذر) تُرك مرّتَين ثمّ نُقل في ١٥ أكتوبر بعد تكبيرِ
   الصورة. ومعه تصحيحٌ لخطإٍ منّي: قلتُ أوّلًا إنّ قيمتَه ١٨ — وذلك على
   أنّه جذرٌ <b>تربيعيّ</b>. والتكبيرُ أظهر مؤشّرَ (٤) على الجذر، فهو جذرٌ
   <b>رابع</b>: <span class=ltr>⁴√(٤×٨١) = ⁴√٤ × ⁴√٨١ = √٢ × ٣ = ٣√٢</span>
   — وهو خيارُ (د)، ومفتاحُ الكتابِ (د). فالثمنُ الوحيدُ للانتظارِ يومَين
   أنّه لم يدخل بجوابٍ خاطئ.

   ── الصيغة ──
   [نصّ السؤال، [الخيارات بترتيبِ الكتاب]، فهرسُ الصحيح، الشرح]
   والخياراتُ بترتيبِ الكتابِ لا بالصحيحِ أوّلًا، لأنّ shuffleQ في
   practice.html تخلطها عند العرضِ وتتبع q[2]. وهذا يحفظ أمرَين معًا:
   نصَّ الكتابِ كما هو، وألّا يتعلّم الطفلُ «اضغط الأوّل» — وهو العطبُ
   الذي وقع في كتابِ المستوى الأول وأُصلح.

   والشرحُ منقولٌ من صفحةِ الحلِّ في الكتابِ نفسِه، وكلُّ سؤالٍ عدديٍّ
   أو منطقيٍّ حُلَّ حلًّا مستقلًّا ثمّ قُورن بمفتاحِ الكتابِ قبل إدخالِه.

   والموقعُ محميٌّ بكلمةِ مرور (gate.js)، والنقلُ لاستعمالِ أبناءِ
   المشتري لا نشرًا عامًّا — وملفُّ الكتابِ نفسُه لا يدخل المستودع. */
